"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["9676"],{7120(e,t,n){n.r(t),n.d(t,{metadata:()=>r,default:()=>d,frontMatter:()=>a,contentTitle:()=>s,toc:()=>c,assets:()=>l});var r=JSON.parse('{"id":"reference/reports","title":"Reporting","description":"alms \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/reference/reports.md","sourceDirName":"reference","slug":"/reference/reports","permalink":"/personal-av-docs/docs/reference/reports","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/reference/reports.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"Reporting","sidebar_label":"Reporting","sidebar_position":99,"edition":"alms","source":"https://doc.airvantage.net/alms/reference/reports","format":"md"}}'),o=n(4848),i=n(8453);let a={title:"Reporting",sidebar_label:"Reporting",sidebar_position:99,edition:"alms",source:"https://doc.airvantage.net/alms/reference/reports",format:"md"},s,l={},c=[];function p(e){let t={a:"a",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsxs)(t.p,{children:[":::note Edition\n",(0,o.jsx)(t.strong,{children:"alms"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,o.jsx)(t.a,{href:"https://doc.airvantage.net/alms/reference/reports",children:"Original page"}),".\n:::"]}),"\n",(0,o.jsx)(t.p,{children:"Reporting\nDevelop\nAirLink Complete\nAccount Management\nManaging Profiles\nToken Stock and ALMS Billing\nMore\nFAQ\nProduct page\nThe Source\nALMS EULA\nGDPR FAQ\nSearching...\nMatching results\nReporting\nAdvanced Mobility Reporting (AMR)\nis an ALMS offering that provides data analysis and historical reporting for your AirLink gateways and routers. AMR is available as part of AirLink Premium with supported devices.\nAMR provides lightweight AVL and fleet management capabilities with its extensive telemetry data collection and reporting features. For better insight into your device status and vehicle behavior, AMR is an ideal low-cost, cloud-based solution. The Reporting section of ALMS is currently available only to AMR users.\nInitializing Table Of Contents...\nSummary of Available Reports\nAMR offers historical reports for:\nCoverage Map\nShows you system network connectivity status during trips within the reporting period. Supports single and multi-radio routers.\nCoverage Trails\nShows you WAN signal strength during trips within the reporting period for routers with a single cellular radio.\nMulti-Radio Coverage Trails\nShows you the specific connectivity status for multiple radios (cellular interfaces) during trips within the reporting period.\nFor routers running AirLink OS only.\nDriver Behavior\nHelp keep your drivers safe and manage performance, measuring driving habits such as hard acceleration, hard deceleration, cornering and speeding.\nEngine Fault Summary\nSchedule maintenance and repairs with a summary of engine faults detected, including time of fault, diagnostic code, total time and distance driven with the MIL activated.\nRequires an OBD-II connection to the vehicle.\nLink Utilization\nProvides a summary of device status and connectivity over time; ideal for identifying connectivity issues that occur at specific times of day.\nFor routers running AirLink OS only.\nOdometer\nRetrieve the distance traveled for a vehicle during a specified period. You can also define a zone for odometer reports, so that any travel within a zone can be included or excluded from the report.\nRequires an OBD-II connection to the vehicle.\nSeat Belt\nProvides an indication of when the driver\u2019s side seat belt is not engaged while the vehicle is moving. You can set a speed threshold for vehicles to be included.\nRequires an OBD-II connection to the vehicle.\nTrip Replay\nShows you an animated view of a vehicle trip.\nTrips\nKnow what your fleet of vehicles has been doing with a historical view of vehicle location, with stop locations, speeding relative to posted limits, and network connectivity status data. Supports single and multi-radio routers.\nVehicle\nSave time in tracking which routers are installed in which vehicles with an inventory of all routers in vehicles, providing the device serial number, the vehicle\u2019s VIN and the total miles driven for each vehicle.\nRequires an OBD-II connection to the vehicle.\nVehicle Utilization\nGet a complete picture of vehicle utilization including total engine time, trip time, idle and PTO time.\nRequires proper vehicle installation of GPIO and an OBD-II connection to the vehicle.\nZone Summary\nProvides a summary of time spent (in hours/minutes and as a percentage) and distance travelled in one or more Zones.\nEach pre-defined report contains unique content focused on a specific purpose. Each report contains tabular and/or map-based results. You can configure any report to schedule the report delivery (daily, weekly, monthly) or run reports on demand; confine the report to a pre-defined region with Zones (geofencing), export reports as PDF, Excel or KML files, and output reports for printing.\nPrerequisites: What you need to use AMR\nBecause AMR is primarily focused on vehicle telemetry reporting, there are a number of hardware and software requirements you must have in place before you can use AMR features. Running reports on other AirLink routers may not yield expected results.\nAirLink Routers\nAMR reports vehicle data for AirLink routers connected to a vehicle. This includes ALEOS-based devices (AirLink GX450 gateways connected using a B&B OBD-II scanner, or MP70, LX60, XR90 and XR80 routers connected directly to a vehicle\u2019s OBD-II or J1939 port) and AirLink XR60 and RX55 routers with vehicle telemetry features enabled.\nAn OBD-II connection between the vehicle and the router is required to collect CAN bus data for the following reports:\nEngine Fault Summary\nOdometer\nSeat Belt\nVehicle\nVehicle Utilization\nAMR also reports routers\u2019 WAN/Cellular usage and connection status, which can be displayed in the following reports:\nCoverage Trails\nMulti-Radio Coverage Trails\nCoverage Map\nLink Utilization\nTrips\nTrips Replay\nAMR supports an external modem connected to a router\u2019s Ethernet port\nfor AirLink OS routers only\n. Semtech has done a custom integration to support HPUE cellular modems. When the external modem is\nconfigured\nand active as the primary WAN interface, it can be displayed in the same way as regular cellular interface. The HPUE modem is considered  another cellular WAN interface to be reported upon in the same manner as the cellular interface(s) on the AirLink router. This provides the same set of link statistics that are currently reported for the cellular interface(s).\nALEOS-based Devices\nAirLink MP70 or LX60\nThe AirLink MP70 router, with its vehicle telemetry capability and inertial sensors, supports all features of AMR.\nNot all LX60 models support vehicle telemetry. Ensure that your LX60 supports Wi-Fi and GNSS and Telemetry before configuring vehicle telemetry and AMR.\nDriver behavior reports require inertial sensors on the router (as supported on the MP70), and will not be reported on an AirLink GX450 or LX60.\nFor optimum reporting performance, connect the router\u2019s ignition line (white wire on the power connector) to the vehicle ignition and connect the router to the vehicle bus as described in the\nMP70 Hardware User Guide\n. Many reports will not function correctly if the router is not wired correctly.\nIn ALEOS, you must also enable:\nVehicle Telemetry (by setting Direct Vehicle Bus Data Collection to\nEnabled: Connected to Ignition\n)\nLocation Service\nDriver Behavior Detection (MP70 only)\nDead Reckoning (MP70 only)\nALEOS Application Framework\nFor more information, see the\nALEOS Software Configuration User Guide for MP70\n(for ALEOS 4.11.0 or later) or the\nALEOS Software Configuration User Guide for LX60\n(for ALEOS 4.13.0 or later).\nMP70 and LX60 routers can collect CAN bus data through an OBD-II (J1979) or J1939 connection from the vehicle\u2019s diagnostic port to the router\u2019s Aux I/O port. See the\nMP70 Hardware User Guide\nand the\nLX60 Hardware User Guide\nfor more information about cable connection and accessories. The OBD-II connection is required for the following reports:\nEngine Fault Summary\nOdometer\nSeat Belt\nVehicle\nVehicle Utilization\nGX450 Gateway\nThe GX450 gateway supports some features of AMR. The gateway must be connected to the vehicle using a B&B OBD-II scanner and Vehicle Telemetry Kit, as described in the\nAirLink Vehicle Telemetry User Guide\n(AVTA 1.1.1 or later).\nConnect the GX450 ignition line (white wire on the power connector) to the vehicle ignition and connect the gateway to the vehicle bus as described in the\nGX450 Hardware User Guide\n.\nThe GX450 supports the following types of reports when correctly installed and configured:\nVehicle Reports\nVehicle Utilization Reports\nEngine Fault Summary Reports\nTrips Reports\nOther ALEOS-based devices may work with some reports (such as Link Utilization), but results will vary. For GPS-based reports, devices with Dead Reckoning will provide the best location accuracy.\nAirLink OS-based Devices\nAirLink XR90, XR80 and RX55 (Wi-Fi and Wi-Fi Plus) Routers\nAirLink XR90 or XR80 routers, with their vehicle telemetry capability and inertial sensors, support all features of AMR.\nRX55 routers do not have inertial sensors; therefore Driver Behavior reports are not supported on the RX55.\nFor optimum reporting performance, connect the router\u2019s ignition line (white wire on the power connector) to the vehicle ignition and connect the router to the vehicle bus as described in the\nXR Series Hardware User Guide\n. Many reports will not function correctly if the router is not wired correctly.\nXR90, XR80 and RX55 (Wi-Fi and Wi-Fi Plus) routers can collect CAN bus data through an OBD-II (J1979) or J1939 connection from the vehicle\u2019s diagnostic port to the router\u2019s Aux I/O port. See the\nXR Series Hardware User Guide\nand\nRX55 Hardware Guide\nfor more information about cable connection and accessories. The OBD-II connection is required for the following reports:\nEngine Fault Summary\nOdometer\nSeat Belt\nVehicle\nVehicle Utilization\nFor instructions on how to enable reporting in AirLink OS, see the:\nXR90 AirLink OS documentation\nXR80 AirLink OS documentation\nRX55 AirLink OS documentation\nAirLink XR60 or RX55 (Base Model) Routers\nAirLink XR60 or RX55 Base Model routers, with their more limited vehicle telemetry features, support AMR reports that don\u2019t require data from the vehicle bus, including:\nTrips\nZone Summary\nTrip Replay\nCoverage Map\nCoverage Trails\nLink Utilization\nFor optimum reporting performance, connect the router\u2019s ignition line (white wire on the power connector) to the vehicle ignition as described in the\nRX55 Hardware User Guide\nand\nXR60 Hardware User Guide\n. Many reports will not function correctly if the router is not wired correctly.\nFor instructions on how to enable reporting in AirLink OS, see the:\nXR60 AirLink OS documentation\nRX55 AirLink OS documentation\nSoftware and Applications\nALEOS\nMP70 routers must be updated to\nALEOS 4.11.0 or later\n.\nLX60 routers must be updated to\nALEOS 4.13.0 or later\n.\nGX450 gateways must be updated to\nALEOS 4.9.3 or later\n.\nThe\nAirVantage Telemetry Application (AVTA) version 1.1.2 or later\nmust be installed from ALMS. The AirLink GX450 with ALEOS 4.9.3 must be used with\nAVTA 1.1.1\n.\nAirLink OS\nFor optimal performance, Semtech recommends upgrading your routers\nXR90, XR80, XR60 and RX55\nto AirLink OS 5.1.78 or later. For report compatibility, see the table below.\nSupported Versions by Report\nREPORT NAME\nSUPPORTS ALEOS\nAVTA VERSION\nSUPPORTS AIRLINK OS\nMINIMUM AIRLINK OS VERSION\nCoverage Map\n1.3.x or later\n4.1\nCoverage Trails\n1.4.2 or later\n4.1\nDriver Behavior\n1.3.x or later\nExcluding XR60\n4.1\nEngine Fault Summary\n1.3.x or later\nExcluding XR60\n5.0\nLink Utilization\nn/a\n4.1\nOdometer\n1.3.x or later\nExcluding XR60\n4.1\nSeat Belt\n1\n1.3.x or later\nExcluding XR60\n4.1\nTrip Replay\n1.3.x or later\n4.1\nTrips\n1.3.x or later\n4.1\nVehicle\n1.3.x or later\nExcluding XR60\n4.1\nVehicle Utilization\n1.3.x or later\nExcluding XR60\n4.1\nZone Summary\n1.3.x or later\n4.1\n1\nSupport is vehicle dependent\nSupported Router Models by Report\nREPORT NAME\nAirLink XR90\nAirLink XR80\nAirLink XR60\nAirLink RX55 Wi-Fi Plus\nAirLink MP70\nAirLink LX60 Wi-Fi+GNSS+Telemetry\nAirLink GX450\nCoverage Map\nCoverage Trails\nDriver Behavior\nEngine Fault Summary\nLink Utilization\nOdometer\nSeat Belt\n1\nTrip Replay\nTrips\nVehicle\nVehicle Utilization\nZone Summary\n1\nSupport is vehicle dependent\nReporting Dashboard\nWhen you click\nReporting\non the top menu, the\nReport Templates\npage appears. This is your reporting dashboard, giving you access to all your reports.\nThe layout of the Report Templates page is user configurable. You can add widgets (as available), move or remove widgets.\nSee\nhere\nfor more information about ALMS dashboards in general.\nThe\nReport Templates\npage is divided into three sections:\nThe\nRecent Reports\nsection. It provides access to the last 5 report instances along with their status, communications history, configuration and management.\nThe\nCreate Report\nbutton opens a blank report template. See\nhere\nfor more information about creating a new report.\nA list of\nReport Templates\nwith additional information provided in columns. You can search for reports using filters.\nRecent Reports\nThe Recent Reports widget shows you the last five reports that were run, along with their status and time of completion.\nTo view a report, click the row for the desired report. See\nViewing Reports\nbelow.\nHovering your mouse over the\nFiles\ncolumn allows you to download the report in its available file format.\nClick the\nRefresh\nbutton on the top right to update the list\nClick\nAll\nto show all the report instances on the\nReports\npage\nPlease note that event datapoints are pre-processed in AirVantage on an hourly schedule before becoming available for AMR report purposes. Because of this, events occurring within the hour before the report execution time (scheduled or on-demand) may not be included in the report.\nReport Status\nEach report status is indicated by color.\nGenerated successfully.\nFailed to generate.\nFailed to export.\nProcessing.\nTimeout.\nIf you click a report that has failed to generate, a message will appear with a link that will take you to the report definition page, where you can edit the report if you wish. Error messages also appear when you click reports that have timed out or are still processing. If a report is still processing, wait until it has completed.\nError messages also appear when you click reports that have timed out or are still processing. If a report is still processing, wait until it has completed.\nIf you click an export file format icon, an error message appears if the file cannot be downloaded in the enabled formats (such as PDF/CSV/KML) because of a file export generation failure, timeout, cancellation, or report processing error. The example on the right shows a KML report generation/export error. Note that when a file export generation failure occurs (the report status is orange), you can still view the report in your browser, as described in\nViewing Reports\nbelow.\nCreate Report\nClick this widget to begin configuring a new report template. For more information, see\nHow to create a new report\n.\nReport Templates List\nThe Report Templates List shows you all the existing report templates for your selected company.\nThe columns displayed can be organized, resized and configured to show the parameters you want to see:\nTo view a report template and see any report instances that have been generated, click the row for the desired report template.\nManage large deployments\nFinding a report or group of reports of interest is easy using filters. Filters can be applied for single or multiple variables: filter on report type, report name, creator, or scheduled (yes/no).\nThe result of the filtered list is displayed on multiple pages if needed.\nSee the example below:\nPerform Report Actions\nThe icons along the top right of the Report Templates list and in the\nActions\ncolumn allow you to perform the actions described below:\nNew Report\nCreate a new report template\nRun\nRun the report, bypassing the report\u2019s schedule\nView\nView the complete report\nEdit\nEdit the report template\nDelete\nDelete the report from the list\nClone\nDuplicate the template of the selected report\nRefresh\nUpdate the reports list\nYou can also perform actions (such as\nDelete\n) for a specific instance of a report in the\nActions\ncolumn, as shown below.\nViewing Reports\nTo view a report:\nGo to\nReporting > Reports\nand then select a report from the table.\nOn the\nRecent Reports\nwidget, click the row for the desired report.\nOn the list of report templates, click the row for the desired report template.\nIf multiple instances of the report have been generated, an interim page appears. It displays a summary of the report template settings along with a list of recently generated reports.\nClick the row for the desired report instance to view the full report details.\nPerform Report Actions\nThe icons along the top right of the report allow you to perform the actions described below:\nRun\nRun the report, bypassing the report\u2019s schedule\nClone\nDuplicate the template of the selected report\nEdit\nEdit the report template\nView raw data points\nView the raw data points used to generate the report. See\nthis page\nfor more information.\nFor more information about reports, see the\nHow-Tos\nsection below.\nHow-Tos\nThis section provides you with helpful procedures for common tasks.\nHow to Create a New Report\nHow to View Raw Data Points\nHow to View and Create Trip Replay Reports\nHow to Work With and Create Coverage Map Reports\nHow to Work With and Create Coverage Trails Reports\nHow to Work With and Create Driver Behavior Reports\nHow to Work With and Create Engine Fault Summary Reports\nHow to Work With and Create Link Utilization Reports\nHow to Work With and Create Multi-Radio Coverage Trails Reports\nHow to Work With and Create Odometer Reports\nHow to Work With and Create Seat Belt Reports\nHow to Work With and Create Trips Reports\nHow to Work With and Create Vehicle Reports\nHow to Work With and Create Vehicle Utilization Reports\nHow to Work With and Create Zone Summary Reports\nHow to install and use AVTC"})]})}function d(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(p,{...e})}):p(e)}},8453(e,t,n){n.d(t,{R:()=>a,x:()=>s});var r=n(6540);let o={},i=r.createContext(o);function a(e){let t=r.useContext(i);return r.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:a(e.components),r.createElement(i.Provider,{value:t},e.children)}}}]);